class Solution:
    def weightedMedian(self, n, edges, queries):
        LOG = max(1, n.bit_length())
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        par = [[0]*n for _ in range(LOG)]; sm = [[0]*n for _ in range(LOG)]; dep = [0]*n
        seen = [False]*n; seen[0] = True; st = [0]; order = []
        while st:
            u = st.pop(); order.append(u)
            for v, w in adj[u]:
                if not seen[v]:
                    seen[v] = True; par[0][v] = u; sm[0][v] = w; dep[v] = dep[u]+1; st.append(v)
        for k in range(1, LOG):
            pk, pp = par[k], par[k-1]; sk, sp = sm[k], sm[k-1]
            for v in range(n):
                p = pp[v]; pk[v] = pp[p]; sk[v] = sp[v] + sp[p]
        def lca(u, v):
            if dep[u] < dep[v]: u, v = v, u
            d = dep[u] - dep[v]
            for k in range(LOG):
                if d >> k & 1: u = par[k][u]
            if u == v: return u
            for k in range(LOG-1, -1, -1):
                if par[k][u] != par[k][v]: u = par[k][u]; v = par[k][v]
            return par[0][u]
        def dist_to(u, w):
            d = dep[u] - dep[w]; s = 0
            for k in range(LOG):
                if d >> k & 1: s += sm[k][u]; u = par[k][u]
            return s
        ans = []
        for u, v in queries:
            if u == v:
                ans.append(u); continue
            w = lca(u, v); du = dist_to(u, w); dv = dist_to(v, w); T = du + dv
            if 2*du >= T:
                x = u; acc = 0
                for k in range(LOG-1, -1, -1):
                    p = par[k][x]
                    if dep[p] >= dep[w] and 2*(acc + sm[k][x]) < T:
                        acc += sm[k][x]; x = p
                ans.append(par[0][x])
            else:
                y = v; acc = 0; lim = 2*du + 2*dv - T
                for k in range(LOG-1, -1, -1):
                    p = par[k][y]
                    if dep[p] >= dep[w] and 2*(acc + sm[k][y]) <= lim:
                        acc += sm[k][y]; y = p
                ans.append(y)
        return ans

