    vector<int> weightedMedian(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        int LOG = 1; while ((1 << LOG) < n) LOG++; LOG = max(LOG, 1);
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        vector<vector<int>> par(LOG, vector<int>(n)), sm(LOG, vector<int>(n));
        vector<int> dep(n); vector<char> seen(n, 0);
        vector<int> st = {0}; seen[0] = 1; vector<int> order;
        while (!st.empty()) { int u = st.back(); st.pop_back(); order.push_back(u);
            for (auto [v, w] : adj[u]) if (!seen[v]) { seen[v] = 1; par[0][v] = u; sm[0][v] = w; dep[v] = dep[u]+1; st.push_back(v); } }
        for (int k = 1; k < LOG; k++) for (int v = 0; v < n; v++) { int p = par[k-1][v]; par[k][v] = par[k-1][p]; sm[k][v] = sm[k-1][v] + sm[k-1][p]; }
        auto lca = [&](int u, int v) {
