            if (u == v) return u;
            for (int k = LOG-1; k >= 0; k--) if (par[k][u] != par[k][v]) { u = par[k][u]; v = par[k][v]; }
            return par[0][u];
        };
        auto distTo = [&](int u, int w) { int d = dep[u] - dep[w]; long long s = 0;
            for (int k = 0; k < LOG; k++) if (d >> k & 1) { s += sm[k][u]; u = par[k][u]; } return s; };
        vector<int> ans;
        for (auto& q : queries) {
            int u = q[0], v = q[1];
            if (u == v) { ans.push_back(u); continue; }
            int w = lca(u, v); long long du = distTo(u, w), dv = distTo(v, w), T = du + dv;
            if (2*du >= T) {
                int x = u; long long acc = 0;
                for (int k = LOG-1; k >= 0; k--) { int p = par[k][x];
                    if (dep[p] >= dep[w] && 2*(acc + sm[k][x]) < T) { acc += sm[k][x]; x = p; } }
                ans.push_back(par[0][x]);
