class Solution {
    public int[] weightedMedian(int n, int[][] edges, int[][] queries) {
        int LOG = 1; while ((1 << LOG) < n) LOG++;
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) { adj[e[0]].add(new int[]{e[1], e[2]}); adj[e[1]].add(new int[]{e[0], e[2]}); }
        int[][] par = new int[LOG][n]; long[][] sm = new long[LOG][n];
        int[] dep = new int[n]; boolean[] seen = new boolean[n];
        Deque<Integer> stk = new ArrayDeque<>(); stk.push(0); seen[0] = true; List<Integer> order = new ArrayList<>();
        while (!stk.isEmpty()) { int u = stk.pop(); order.add(u);
            for (int[] vw : adj[u]) { int v = vw[0], w = vw[1]; if (!seen[v]) { seen[v] = true; par[0][v] = u; sm[0][v] = w; dep[v] = dep[u]+1; stk.push(v); } } }
        for (int k = 1; k < LOG; k++) for (int v = 0; v < n; v++) { int p = par[k-1][v]; par[k][v] = par[k-1][p]; sm[k][v] = sm[k-1][v] + sm[k-1][p]; }
        class H { int lca(int u, int v) { if (dep[u] < dep[v]) { int t = u; u = v; v = t; }
            int d = dep[u] - dep[v]; for (int k = 0; k < LOG; k++) if ((d >> k & 1) == 1) u = par[k][u];
            if (u == v) return u;
            for (int k = LOG-1; k >= 0; k--) if (par[k][u] != par[k][v]) { u = par[k][u]; v = par[k][v]; }
            return par[0][u]; }
            long distTo(int u, int w) { int d = dep[u] - dep[w]; long s = 0; for (int k = 0; k < LOG; k++) if ((d >> k & 1) == 1) { s += sm[k][u]; u = par[k][u]; } return s; } }
        H h = new H();
        int[] ans = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int u = queries[qi][0], v = queries[qi][1];
            if (u == v) { ans[qi] = u; continue; }
            int w = h.lca(u, v); long du = h.distTo(u, w), dv = h.distTo(v, w), T = du + dv;
            if (2*du >= T) {
                int x = u; long acc = 0;
                for (int k = LOG-1; k >= 0; k--) { int p = par[k][x];
                    if (dep[p] >= dep[w] && 2*(acc + sm[k][x]) < T) { acc += sm[k][x]; x = p; } }
                ans[qi] = par[0][x];
            } else {
                int y = v; long acc = 0, lim = 2*du + 2*dv - T;
                for (int k = LOG-1; k >= 0; k--) { int p = par[k][y];
                    if (dep[p] >= dep[w] && 2*(acc + sm[k][y]) <= lim) { acc += sm[k][y]; y = p; } }
                ans[qi] = y;
            }
        }
        return ans;
    }
}

